#[path = "src/inflection/mod.rs"]
mod inflection;

use std::env;

fn main() {
    inflection::Inflector::initialize();

    let args: Vec<String> = env::args().collect();
    let argc = args.len();
    let mut all_results: Vec<String> = Vec::new();

    if argc > 1 {
        let base_word = &args[1];

        all_results.push(inflection::Inflector::pluralize(base_word));
        all_results.push(inflection::Inflector::singularize(base_word));
        all_results.push(inflection::Inflector::camelize(base_word));
        all_results.push(inflection::Inflector::camelize_with_flag(base_word, false));
        all_results.push(inflection::Inflector::underscore(base_word));

        all_results.push(inflection::Inflector::classify(base_word));
        all_results.push(inflection::Inflector::tableize(base_word));
        all_results.push(inflection::Inflector::humanize(base_word));
        all_results.push(inflection::Inflector::titleize(base_word));
        all_results.push(inflection::Inflector::dasherize(base_word));

        all_results.push(inflection::Inflector::parameterize(base_word));
        all_results.push(inflection::Inflector::parameterize(&format!("A {} Test", base_word)));
        all_results.push(inflection::Inflector::upcase(base_word));
        all_results.push(inflection::Inflector::downcase(base_word));
        all_results.push(inflection::Inflector::capitalize(base_word));

        all_results.push(inflection::Inflector::decapitalize(base_word));
        all_results.push(inflection::Inflector::truncate(base_word, 5));
        all_results.push(inflection::Inflector::demodulize(&format!("Test::{}", base_word)));
        all_results.push(inflection::Inflector::is_plural(base_word).to_string());
        all_results.push(inflection::Inflector::is_singular(base_word).to_string());
    }

    if all_results.len() < 20 && argc > 1 {
        for value in 1..=5 {
            if all_results.len() >= 20 {
                break;
            }
            all_results.push(inflection::Inflector::ordinalize(value));
        }
    }

    for value in all_results.iter().take(20) {
        println!("{value}");
    }
}

