    let mut result = String::with_capacity(word.len() + 1);
    result.push_str(word);
    result.push('s');
    result
}

pub fn singularize(word: &str) -> String {
    match word.strip_suffix('s') {
        Some(prefix) => prefix.to_string(),
        None => word.to_string(),
    }
}

pub fn camelize(word: &str) -> String {
    let mut result = String::with_capacity(word.len());
    let mut uppercase_next = false;

    for ch in word.chars() {
        if ch == '_' {
            uppercase_next = true;
            continue;
        }

        if uppercase_next {
            result.push(ch.to_ascii_uppercase());
            uppercase_next = false;
        } else {
            result.push(ch);
        }
    }

    result
}

pub fn camelize_with_flag(word: &str, lowercase_first_letter: bool) -> String {
    let result = camelize(word);
    if lowercase_first_letter {
        ascii::lowercase_first(&result)
    } else {
        ascii::uppercase_first(&result)
    }
}

pub fn underscore(word: &str) -> String {
    let mut result = String::with_capacity(word.len() * 2);

    for ch in word.chars() {
        if ch.is_ascii_uppercase() {
            if !result.is_empty() {
                result.push('_');
            }
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
    }

    result
}

pub fn classify(word: &str) -> String {
    camelize_with_flag(&singularize(word), false)
}

pub fn tableize(word: &str) -> String {
    pluralize(&underscore(word))
}

pub fn humanize(word: &str) -> String {
    ascii::uppercase_first(&word.replace('_', " "))
}

pub fn titleize(word: &str) -> String {
    word.split(' ')
        .map(ascii::capitalize)
        .collect::<Vec<_>>()
        .join(" ")
}

pub fn dasherize(word: &str) -> String {
    word.replace('_', "-")
}

pub fn parameterize(word: &str) -> String {
    let mut result = String::with_capacity(word.len());

    for ch in word.chars() {
        if ch.is_ascii_alphanumeric() {
            result.push(ch.to_ascii_lowercase());
        } else if ch == ' ' {
            result.push('-');
        }
    }

    result
}

pub fn upcase(word: &str) -> String {
    ascii::upcase(word)
}

pub fn downcase(word: &str) -> String {
    ascii::downcase(word)
}

pub fn capitalize(word: &str) -> String {
    ascii::capitalize(word)
}

pub fn decapitalize(word: &str) -> String {
    ascii::lowercase_first(word)
}

pub fn truncate(word: &str, length: usize) -> String {
    if word.len() <= length {
        return word.to_string();
    }

    if length <= 3 {
        return ".".repeat(length);
    }

    let mut result = String::with_capacity(length);
    result.push_str(&word[..length - 3]);
    result.push_str("...");
    result
}

pub fn demodulize(word: &str) -> String {
    if let Some(pos) = word.rfind(':') {
        let start = pos + 2;
        if start > word.len() {
            process::abort();
        }

        return word[start..].to_string();
    }

    word.to_string()
}

pub fn is_plural(word: &str) -> i32 {
    i32::from(word.ends_with('s'))
}

pub fn is_singular(word: &str) -> i32 {
    i32::from(!word.ends_with('s'))
}

pub fn ordinalize(value: i32) -> String {
    let suffix = match value.abs() % 100 {
        11..=13 => "th",
        _ => match value.abs() % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };

    format!("{value}{suffix}")
}

